private readonly ConcurrentDictionary<string, Session> _sessions = new();
Session Get(string key) => _sessions.GetOrAdd(key, k => Session.Open(k));

private readonly Lock[] _stripes =
    Enumerable.Range(0, 64).Select(_ => new Lock()).ToArray();

void Put(string key, Value v)
{
    lock (_stripes[(uint)key.GetHashCode() % 64u]) { state[key] = v; }
}
